// @name Immich videos
// Videos from a self-hosted Immich server, one after another: random ones
// from the whole library, an album or the favorites. The frame plays Immich's
// own stream of each (its transcoded copy when it made one), with the key from
// the frame's Immich settings; when or where it was taken shows for a moment
// at the start. A tap skips to the next. Plays on a Raspberry Pi
// (docs/video.md).
const BATCH = 12
const RETRY_MS = 30000
const CAPTION_MS = 6000

let queue = [] // assets to play next
let current = null // { id, name, date, place }
let startedAt = 0
let problem = ''
let problemAt = 0
let lastFilter = ''
const failed = new Set() // assets that did not play, skipped from then on

function request(server, key, url, method = 'GET', body = '') {
  const headers = { 'x-api-key': key, Accept: 'application/json', 'Content-Type': 'application/json' }
  return frameos.httpRequest(`${server}${url}`, { method, headers, body, timeoutMs: 30000 })
}

function httpError(r) {
  if (r.status === 0) return r.error ? `request failed: ${r.error}` : 'request failed'
  try {
    const json = JSON.parse(r.body ?? '')
    if (typeof json?.message === 'string') return `HTTP ${r.status}: ${json.message}`
  } catch {}
  return `HTTP ${r.status}`
}

function place(exif) {
  return [exif?.city, exif?.country].filter((part) => typeof part === 'string' && part).join(', ')
}

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']

function day(text) {
  // The day it was taken as Immich wrote it (its own time zone), "12 March 2024".
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(text ?? ''))
  return m ? `${Number(m[3])} ${MONTHS[Number(m[2]) - 1] ?? ''} ${m[1]}` : ''
}

function fetchBatch(app, server, key) {
  const search = { size: BATCH, type: 'VIDEO', withExif: true }
  const albumId = String(app.state.albumId ?? '').trim()
  if (app.state.mode === 'album' && albumId) search.albumIds = [albumId]
  if (app.state.mode === 'favorites') search.isFavorite = true
  const r = request(server, key, '/api/search/random', 'POST', JSON.stringify(search))
  if (r.status !== 200) throw new Error(`Immich did not give videos: ${httpError(r)}`)
  let list = []
  try {
    list = JSON.parse(r.body ?? '[]')
  } catch {}
  const videos = (Array.isArray(list) ? list : [])
    .filter((a) => a && a.type === 'VIDEO' && a.id)
    .map((a) => ({
      id: String(a.id),
      name: String(a.originalFileName ?? ''),
      date: day(a.exifInfo?.dateTimeOriginal ?? a.fileCreatedAt),
      place: place(a.exifInfo),
    }))
  if (!videos.length) {
    throw new Error(
      app.state.mode === 'album'
        ? 'This album holds no videos. The album ID is the UUID in its URL.'
        : app.state.mode === 'favorites'
          ? 'No favorite videos in Immich.'
          : 'Immich has no videos.'
    )
  }
  return videos
}

function next(app, server, key) {
  for (let i = 0; i < BATCH * 2; i++) {
    if (!queue.length) queue = fetchBatch(app, server, key)
    current = queue.shift()
    if (!failed.has(current.id)) break
  }
  startedAt = Date.now()
}

function Message({ title, text, k }) {
  return (
    <div className="w-full h-full flex flex-col items-center justify-center bg-black text-white gap-[8px] px-[24px]">
      <span className={`text-[${Math.round(22 * k)}px] font-bold`}>{title}</span>
      <span className={`text-[${Math.round(15 * k)}px] text-white/70 text-center`}>{text}</span>
    </div>
  )
}

export function get(app, context) {
  const width = context?.imageWidth ?? app.frame.width
  const height = context?.imageHeight ?? app.frame.height
  const k = Math.max(0.6, Math.min(1.6, Math.min(width / 800, height / 480) * 1.15))
  const server = String(frameos.getSetting('immich', 'url') ?? '').replace(/\/+$/, '')
  const key = String(frameos.getSetting('immich', 'apiKey') ?? '')
  if (!server || !key) {
    return <Message k={k} title="Immich videos" text="Add your Immich server's address and an API key in the frame's settings (Immich)." />
  }
  const filter = `${app.state.mode}|${app.state.albumId}`
  if (filter !== lastFilter) {
    lastFilter = filter
    queue = []
    current = null
  }
  if (problem && Date.now() - problemAt < RETRY_MS) {
    frameos.setNextSleep(Math.max(1, (RETRY_MS - (Date.now() - problemAt)) / 1000))
    return <Message k={k} title="Immich videos" text={problem} />
  }
  try {
    if (!current) next(app, server, key)
    problem = ''
  } catch (error) {
    problem = String(error?.message ?? error)
    problemAt = Date.now()
    frameos.setNextSleep(RETRY_MS / 1000)
    return <Message k={k} title="Immich videos" text={problem} />
  }
  const fit = app.state.fit === 'cover' ? 'cover' : 'contain'
  const longest = Number(app.state.longest) || 0
  const playCurrent = () =>
    frameos.video('immich', {
      src: `${server}/api/assets/${encodeURIComponent(current.id)}/video/playback`,
      headers: { 'x-api-key': key },
      fit,
      fps: Number(app.state.fps) || 30,
    })
  let video = playCurrent()
  const tooLong = longest > 0 && video.state === 'playing' && Date.now() - startedAt > longest * 60000
  if (video.state === 'ended' || tooLong || (video.state === 'error' && video.id !== 0)) {
    if (video.state === 'error') {
      frameos.log(`Skipping ${current.name || current.id}: ${video.error}`)
      failed.add(current.id)
    }
    const before = current.id
    try {
      next(app, server, key)
    } catch (error) {
      problem = String(error?.message ?? error)
      problemAt = Date.now()
      return <Message k={k} title="Immich videos" text={problem} />
    }
    // The same one again (a library of one): from its start.
    if (current.id === before) frameos.releaseVideo(video)
    video = playCurrent()
  }
  if (video.state === 'error') {
    // No video here at all (an ESP32, the preview), or one the frame may not
    // open (a cloud frame's Local network access): said, and tried again later.
    const here = video.id === 0 && /cannot play it|, not here/.test(video.error || '')
    if (!here) {
      problem = video.error || 'The video did not play.'
      problemAt = Date.now()
      current = null
    }
    return <Message k={k} title={here ? 'Video does not play here' : 'Immich videos'} text={video.error} />
  }
  const caption = app.state.caption !== false && Date.now() - startedAt < CAPTION_MS
  if (caption) frameos.setNextSleep(Math.max(0.5, (CAPTION_MS - (Date.now() - startedAt)) / 1000))
  const words = [current.date, current.place].filter(Boolean).join(' · ')
  return (
    <div className="relative w-full h-full bg-black" onClick={() => { current = null }}>
      <img className={`w-full h-full object-${fit}`} src={video} />
      {caption && words ? (
        <div className={`absolute left-[${Math.round(16 * k)}px] bottom-[${Math.round(14 * k)}px] px-[12px] py-[6px] rounded-[8px] bg-black/55`}>
          <span className={`text-[${Math.round(16 * k)}px] text-white`}>{words}</span>
        </div>
      ) : null}
    </div>
  )
}
